import type { DirectionRef } from './direction-ref';
import type { VariantReference } from './variant-reference';
export type { VariantReference } from './variant-reference';

export type VariantHistoryStatus =
  'completed' | 'committed' | 'rejected' | 'cancelled' | 'removed';

export type VariantHistoryKind = 'diff' | 'project-created';

export type VariantHistoryPreview =
  | {
      kind: 'static';
      rootPath: 'files';
      entryPath: string;
    }
  | {
      kind: 'dev-server';
      rootPath: 'files';
      command: {
        cwd: string;
        packageManager: string;
        script: string;
      };
      runnablePath?: string;
    }
  | {
      kind: 'none';
      reason: 'diff_only' | 'missing_entry' | 'unsupported';
    };

export type PersistVariantPreview =
  | { kind: 'static'; entryPath: string }
  | {
      kind: 'dev-server';
      command: {
        cwd: string;
        packageManager: string;
        script: string;
      };
      runnablePath?: string;
    }
  | { kind: 'none'; reason: 'diff_only' | 'missing_entry' | 'unsupported' };

export interface VariantTreePointer {
  ref: string;
  commitSha: string;
  treeSha: string;
}

export interface VariantBasePointer {
  ref: string;
  commitSha: string;
}

export interface DevServerRecipe {
  cwd: string;
  cmd: string;
  argsTemplate: string[];
  envTemplate?: Record<string, string>;
}

export type VariantServeSpec =
  | { kind: 'static'; entryPath: string }
  | { kind: 'dev-server'; recipe: DevServerRecipe };

export type VariantHistoryArtifact =
  | {
      kind: 'diff';
      diffPath: 'diff.patch';
      filesPath?: 'files';
    }
  | {
      kind: 'project';
      filesPath: 'files';
      runnablePath?: string;
    };

export interface VariantDesignSource {
  kind: 'slug' | 'markdown';
  label: string;
  slug?: string;
}

export interface VariantDeployment {
  deployId: string;
  shareUrl: string;
  deployedAt: string;
}

export interface VariantCanvasDeployment {
  deployId: string;
  shareUrl: string;
  deployedAt: string;
  variants: Array<{
    variantId: string;
    deployId: string;
    shareUrl: string;
  }>;
}

export interface VariantHistoryManifest {
  previewRoutes?: string[];
  schemaVersion: number;
  variantId: string;
  sessionId: string;
  requestId?: string;
  directionRef?: DirectionRef;
  label: string;
  brief: string;
  references?: VariantReference[];
  sessionPrompt: string;
  runLabel?: string;
  projectKind: 'existing' | 'fresh';
  status: VariantHistoryStatus;
  createdAt: string;
  statusChangedAt: string;
  baseSha?: string;
  destinationPath?: string;
  changedFilesCount: number;
  artifact: VariantHistoryArtifact;
  preview: VariantHistoryPreview;
  tree?: VariantTreePointer;
  base?: VariantBasePointer;
  parent?: { ref: string; commitSha: string };
  parentVariant?: { sessionId: string; variantId: string };
  serve?: VariantServeSpec;
  designSource?: VariantDesignSource;
  deployments?: VariantDeployment[];
  runtime?: import('../agent-variants/contracts').WorkerRuntimeInfo;
}

export type VariantHistoryRow = Pick<
  VariantHistoryManifest,
  | 'sessionId'
  | 'variantId'
  | 'requestId'
  | 'directionRef'
  | 'label'
  | 'brief'
  | 'references'
  | 'previewRoutes'
  | 'runLabel'
  | 'projectKind'
  | 'status'
  | 'createdAt'
  | 'statusChangedAt'
  | 'changedFilesCount'
  | 'preview'
  | 'artifact'
  | 'parentVariant'
  | 'serve'
  | 'runtime'
> & { kind: VariantHistoryKind; hasStaticPreview: boolean; hasTree: boolean };

export interface VariantHistorySessionFile {
  schemaVersion: number;
  sessionId: string;
  createdAt: string;
  sessionPrompt: string;
  projectKind: 'existing' | 'fresh';
  canvasDeployments?: VariantCanvasDeployment[];
}

export interface VariantIndexEntry {
  manifest: VariantHistoryManifest;
  hasStaticPreview: boolean;
}

export interface VariantIndexEntryInput extends VariantIndexEntry {
  manifestMtimeMs: number;
}
